function icon(key, size, cls) {
  const inner = ICON_SVG[key];
  if (!inner) return "";
  const s = size || 24;
  return `<svg class="ico ${cls || ''}" viewBox="0 0 512 512" width="${s}" height="${s}" aria-hidden="true" focusable="false" fill="currentColor">${inner}</svg>`;
}
